<?php
declare(strict_types=1);
require dirname(__DIR__) . '/lib.php';
if(!(cfg()['telegram']['terminal_enabled'] ?? true)){http_response_code(403);exit('Terminal disabled');}
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><title>OpenWrt SSH Console</title>
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;background:#0b0f14;color:#e6edf3}.wrap{max-width:900px;margin:auto;padding:14px}.card{background:#111821;border:1px solid #263241;border-radius:14px;padding:14px;margin-bottom:12px}.row{display:flex;gap:8px;flex-wrap:wrap}input,button{font:inherit;border-radius:9px;border:1px solid #334155;padding:10px;background:#0f1720;color:#e6edf3}input{flex:1;min-width:120px}button{cursor:pointer;background:#172554}button:disabled{opacity:.5}.term{min-height:50vh;max-height:62vh;overflow:auto;white-space:pre-wrap;word-break:break-word;background:#020617;padding:12px;border-radius:10px;border:1px solid #1e293b}.cmd{width:100%;margin-top:8px}.muted{color:#94a3b8;font-size:12px}.ok{color:#86efac}.bad{color:#fca5a5}
</style></head><body><div class="wrap"><div class="card"><b>OpenWrt SSH Console</b><div class="muted">Authenticated through local Dropbear on the router. Credentials stay in this Mini App memory and are sent only with each command.</div><div class="row" style="margin-top:10px"><input id="user" value="root" placeholder="Username"><input id="pass" type="password" placeholder="OpenWrt password"><button id="connect">Connect</button></div><div id="status" class="muted" style="margin-top:8px">Not connected</div></div><div class="card"><div id="term" class="term">PW Agent SSH Console v0.4.0\n</div><div class="row"><input id="cmd" class="cmd" placeholder="Type a command…" autocomplete="off" autocapitalize="off"><button id="run">Run</button></div><div class="muted">Non-interactive SSH console: shell commands work; full-screen TTY apps such as vi/top are not interactive.</div></div></div>
<script>
const tg=window.Telegram.WebApp;tg.ready();tg.expand();let connected=false,cwd='/root';
const $=id=>document.getElementById(id), term=$('term'), status=$('status');
function out(s,cls=''){let d=document.createElement('div');if(cls)d.className=cls;d.textContent=s;term.appendChild(d);term.scrollTop=term.scrollHeight}
async function execCmd(command){const username=$('user').value.trim(),password=$('pass').value;if(!username||!password)throw new Error('Enter username and password');let r=await fetch('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:tg.initData,username,password,command,cwd})});let j=await r.json();if(!j.ok)throw new Error(j.error||'Command failed');cwd=(j.result&&j.result.cwd)||cwd;return j.result||{};}
$('connect').onclick=async()=>{try{$('connect').disabled=true;status.textContent='Connecting…';let r=await execCmd('printf __PWTERM_OK__');if(String(r.output||'').includes('__PWTERM_OK__')){connected=true;status.innerHTML='<span class="ok">Connected</span> · '+cwd;out('Connected to OpenWrt via SSH.','ok')}else throw new Error('Authentication check failed')}catch(e){connected=false;status.innerHTML='<span class="bad">'+e.message+'</span>';out(e.message,'bad')}finally{$('connect').disabled=false}};
async function run(){let c=$('cmd').value;if(!c.trim())return;if(!connected){out('Connect first.','bad');return}$('cmd').value='';out('root@Gale:'+cwd+'# '+c);$('run').disabled=true;try{let r=await execCmd(c);if(r.output)out(r.output);status.textContent='Connected · '+cwd+' · exit '+(r.exit_code??0)}catch(e){out(e.message,'bad')}finally{$('run').disabled=false;$('cmd').focus()}}
$('run').onclick=run;$('cmd').addEventListener('keydown',e=>{if(e.key==='Enter')run()});
</script></body></html>
